        while ((uint64_t)z_t3260_entries_cap(_p2) < _capacity && _p2 < 0x40000000u) {
            _p2 <<= 1;
        }
        _this.capacity = _p2;
        _this.entries = (z_t3260_entry_t*)z_xcalloc(
            z_t3260_entries_cap(_p2), sizeof(z_t3260_entry_t));
        if (_p2 > Z_T3260_SMALL_MAX) {
            _this.indices = (uint32_t*)z_xcalloc(_p2, sizeof(uint32_t));
        }
